import unittest
from src.server import app

class TestAuth(unittest.TestCase):
    def setUp(self):
        self.client = app.test_client()

    def test_login(self):
        # This test uses admin credentials
        response = self.client.post('/login', data=dict(
            username='admin',
            password='admin123'
        ))
        self.assertIn('Logged in', str(response.data))

